@push('scripts')<script>
document.getElementById('analyser-couverture-ia').addEventListener('click',async function(){const out=document.getElementById('couverture-ia-resultat');this.disabled=true;out.textContent='Analyse en cours…';try{const response=await fetch('{{ route('admin.plans-urgence.ia') }}',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({action:'couverture'})});const data=await response.json();if(!response.ok)throw new Error(data.message||'Analyse indisponible.');out.replaceChildren();for(const key of ['lacunes','actions']){const section=document.createElement('section');const heading=document.createElement('h6');heading.textContent=key==='lacunes'?'Lacunes':'Actions recommandées';section.append(heading);const list=document.createElement('ul');data[key].forEach(item=>{const li=document.createElement('li');li.textContent=item;list.append(li);});section.append(list);out.append(section);}}catch(e){out.textContent=e.message;}finally{this.disabled=false;}});
</script>@endpush
